local _, WFJ = ...
WFJ.Data.add("quest", {
  [65593] = { "恋人たちの心", "Avelina LillyとIsaac Pearsonの心臓を、Temple of the DamnedにいるCarendin Halgarのところへ持って行ってください。", "incubusは恋人たちの心に引き寄せられる。そして最も切ない恋こそが、最も抗いがたい誘惑となるのだ。\n\n私の占いで、とりわけ役に立ちそうな二人が見つかった。\n\nSilverpine Forestでは、Avelina LillyがAmbermillの堕ちた魔法使いたちに仕立ての腕を振るっている。Barrensでは、Isaac Pearsonが海辺の町Ratchetで名を上げようとしている。\n\n二人は世界の両端で働いているが、その心は互いだけを求めている。その心をCarendinのもとへ持ってこい。", nil, nil, 0x55692d12, 0x61c7ffbd, 0x14a38dc7, nil, nil, "...mm" },
  [65597] = { "束縛", "Lovers' Heartsを使ってincubusを召喚して服従させ、Lovers' HeartsをUndercityのMagic QuarterにいるCarendin Halgarのところへ返して下さい。", "ついにその時が来た。心臓を下の召喚の円へ持っていけ。その中心に置き、incubusを呼び出すのだ。\n\n罠におびき寄せられたと気づけば、あの悪魔は機嫌を損ねるだろう。その誘惑の餌食になるなよ、{name}。完全に屈服させねばならん。\n\nそうして初めて、そいつをお前の意のままに縛る呪文を教えてやれる。", nil, nil, 0x5926988f, 0xf62852d5, 0x71f56f10, nil, nil, "...mm" },
  [65601] = { "愛の痛み", "OrgrimmarにいるMagarと話してください。", "sayaadの雄はincubusと呼ばれる。底知れぬ邪悪さと、ただ一つの目的を持つ生き物だ。\n\nその悪魔は、誘惑の品――大いなる愛と献身を表すもの――で我らの世界へおびき寄せねばならん。\n\n盲目の男に導かれることを信じるなら、{name}、よく聞け。Cleft of Shadowから東、Orgrimmarの大通り沿いにMagarが住んでいる。あいつは連れ合いのKrilgeが戻ってくるのを待ち焦がれている。\n\nあいつを訪ねろ。何か大切なものを探してくれと頼まれるはずだ。それこそが、お前がGan'rulのもとへ持っていかねばならぬ鍵だ。", nil, nil, 0x3399fa86, 0x4cd2fb90, 0xc9b1e252, nil, nil, "...mm" },
  [65602] = { "愛とは何か？", "Wooden Figurineを取り戻し、StormwindのMage QuarterにいるGakin the Darkbinderのところへ持って行ってください。", "incubusを誘惑するには強力な触媒が必要だ――大いなる献身と愛を表す品がな。\n\n私の占いで、お前の儀式にふさわしそうな小さなfigurineを見つけた。\n\n何千年も前、そのfigurineはある若い恋人たちのものだった。元の持ち主はもういないが、その形見は今日まで残っているのだ。\n\n道を北へたどってAshenvaleに入り、それから西へ進んでMaestra's Postを過ぎろ。木々の間にひっそりと建つ家が見えるはずだ。そこに、お前の探しているものがある。", nil, nil, 0x734eb18b, 0x5911c632, 0xd1ace9bb, nil, nil, "...mm" },
  [65603] = { "束縛", "Wooden Figurineを使ってincubusを召喚して屈服させ、Slaughtered LambにいるGakin the DarkbinderにWooden Figurineを返してください。", "時は来た。figurineを持って、下の地下墓所へ降りていけ。召喚の円陣が用意してある。その中心にfigurineを置くのだ。\n\nそうすれば門が開き、incubusが我らの世界へと渡ってくる。\n\nsayaadを侮ってはならん。その悪魔は、お前の策略に気づけばためらわず襲いかかってくるだろう。これまでに教わったすべてを駆使して、それを打ち倒さねばならん。\n\n成功したら私のもとへ戻れ。その生き物をお前の意のままに縛りつけてやろう。失敗すれば、お前の魂は失われる。", nil, nil, 0x5926988f, 0x9a339fad, 0xfe44a9e9, nil, nil, "...mm" },
  [65604] = { "束縛", "Withered Scarfを使ってincubusを召喚して服従させ、Withered ScarfをOrgrimmarのGan'rul Bloodeyeのところへ返して下さい。", "そうか……分かったぞ。この糸に込められた感情の名残を感じる。その縫い目には愛が織り込まれている。incubusは抗えまい。\n\nこれをNeeruのテントにある召喚の円へ持っていけ、{name}。悪意あるincubusを呼び出し、お前の腕前を見せつけてやれ。大人しく屈服するとは思うな。魔法を用意し、戦いに備えろ。悪魔を侮ったことが、多くのウォーロックにとって最後の過ちとなってきたのだ。\n\nそいつを倒したら、その布を私に返せ。お前が見つけたことはMagarに伝えておこう。", nil, nil, 0x5926988f, 0x4de62da3, 0xae8e63dd, nil, nil, "...mm" },
  [65610] = { "君がここにいれば", "AshenvaleのFallen Sky Lakeを調査し、わかったことをOrgrimmarにいるGan'rul Bloodeyeに報告してください。", "KrilgeとはAshenvaleでMoonclothを作っていた時に出会ったの。彼は民間人を危険から守るためにそこに配属されていたんだけど、ある時姿を消してしまって……\n\nみんなもう彼を探すのをやめて、脱走兵だと見なしているけど、私はそんなこと信じないわ。\n\n私たちはよくFallen Sky Lakeで会っていたの。あの攻撃的なbog beastたちに占拠されてしまう前はね。\n\n普段は人に頼み事なんてしないんだけど、もしAshenvaleへ行って彼の手がかりを探してくれたら、ありがたいわ。", nil, nil, 0x32bcc5f5, 0x552d2de9, 0x7f76fd7c, nil, nil, "...mm" },
})
